-- Pre-generated session-level admin_comment + next_suggested_question
-- live on the session row so the admin UI can render them the moment
-- the user-detail page loads — no extra round-trip to a separate
-- predictions table.
--
-- Distinct from per-snippet ai_draft_admin_comment on charisma_snippets:
-- those are per-clip suggestions, this pair is the SESSION-LEVEL
-- "what would you tell this user overall + what should we ask
-- them next" — the two fields the admin_annotations_log captures
-- as the RLHF training pair.
--
-- Generated by services/session_predictions.generate_session_predictions
-- during finalize, immediately after kpi_narrative. Failure-isolated:
-- a missing prediction just leaves these columns NULL.
--
-- Run in Supabase SQL Editor. Idempotent.

DO $$ BEGIN
  IF NOT EXISTS (
    SELECT 1 FROM information_schema.columns
    WHERE table_schema = 'public'
      AND table_name = 'v2_sessions'
      AND column_name = 'ai_predicted_session_comment'
  ) THEN
    ALTER TABLE v2_sessions
      ADD COLUMN ai_predicted_session_comment TEXT DEFAULT NULL;
  END IF;

  IF NOT EXISTS (
    SELECT 1 FROM information_schema.columns
    WHERE table_schema = 'public'
      AND table_name = 'v2_sessions'
      AND column_name = 'ai_predicted_next_question'
  ) THEN
    ALTER TABLE v2_sessions
      ADD COLUMN ai_predicted_next_question TEXT DEFAULT NULL;
  END IF;

  IF NOT EXISTS (
    SELECT 1 FROM information_schema.columns
    WHERE table_schema = 'public'
      AND table_name = 'v2_sessions'
      AND column_name = 'ai_predictions_generated_at'
  ) THEN
    ALTER TABLE v2_sessions
      ADD COLUMN ai_predictions_generated_at TIMESTAMPTZ DEFAULT NULL;
  END IF;
END $$;

COMMENT ON COLUMN v2_sessions.ai_predicted_session_comment IS
  'LLM-pre-written session-level admin_comment, generated during '
  'finalize. The admin sees this in the user-detail panel and can '
  'accept or edit before clicking Publish. The (predicted, final) '
  'pair becomes one row in admin_annotations_log.';

COMMENT ON COLUMN v2_sessions.ai_predicted_next_question IS
  'LLM-pre-written suggested next coaching question for this '
  'user. Same admin-review + RLHF logging path as the comment.';

COMMENT ON COLUMN v2_sessions.ai_predictions_generated_at IS
  'When the predictions were last (re)generated. Lets the admin '
  'UI surface staleness (e.g. "Predictions from 2h ago — '
  'regenerate?" if metrics changed since).';
